import json
from pathlib import Path
rows=[
('a2-past','A2','Завершённые события','Perfect compus','Прошедшее завершённое действие передаётся вспомогательными am, ai, a, am, ați, au и причастием: am citit. Причастие в этой конструкции не согласуется с подлежащим. Отрицание стоит перед вспомогательным: nu am citit.','Не ставьте a перед причастием: am citit, а не am a citit.',[
('Ieri am lucrat acasă.','Вчера я работал дома.'),('Ai citit mesajul?','Ты прочитал сообщение?'),('Ea a venit dimineață.','Она пришла утром.'),('Nu am înțeles întrebarea.','Я не понял вопрос.'),('Am cumpărat două bilete.','Мы купили два билета.')],('Он пришёл: El ___ venit.','a','Для третьего лица единственного числа используется a.')),
('a2-future','A2','Планы и обещания','Viitor','Для литературного будущего используйте voi, vei, va, vom, veți, vor и инфинитив без a: voi merge. В разговоре часто используется o să + conjunctiv: o să merg. Обе конструкции обозначают будущее; не смешивайте части двух моделей.','В данном уроке тренируем voi + инфинитив. Местоимение можно опустить, но форма вспомогательного остаётся.',[
('Mâine voi merge la medic.','Завтра я пойду к врачу.'),('Vei primi un mesaj.','Ты получишь сообщение.'),('Trenul va pleca la timp.','Поезд отправится вовремя.'),('Vom discuta după ședință.','Мы поговорим после совещания.'),('Vă voi suna mâine.','Я позвоню вам завтра.')],('Мы придём: Noi ___ veni.','vom','Будущее для noi: vom + veni.')),
('a2-cases','A2','Чей предмет и кому?','Genitiv și dativ','Родительный отвечает на вопрос принадлежности, дательный — кому. В определённых формах часто совпадают: cartea fetei — книга девочки, îi dau fetei o carte — даю девочке книгу. Мужская форма: copilului; множественное число: copiilor.','Не заменяйте все падежные конструкции предлогом de: важно различать конкретного владельца и общий признак.',[
('Aceasta este cartea fetei.','Это книга девочки.'),('Îi dau copilului o carte.','Я даю ребёнку книгу.'),('Ușa camerei este deschisă.','Дверь комнаты открыта.'),('Numele profesorului este Ionescu.','Фамилия преподавателя — Ионеску.'),('Le explic elevilor regula.','Я объясняю ученикам правило.')],('Книга ребёнка: cartea ___ (copilul)','copilului','Определённая форма родительного: copilului.')),
('a2-pronouns','A2','Короткие местоимения','Îl, o, îi','Безударные местоимения занимают позицию около глагола: îl văd — вижу его, o văd — вижу её. Для косвенного дополнения единственного числа используется îi. В сложном прошедшем женское o обычно идёт после причастия: am văzut-o.','Следите за прямым и косвенным дополнением: вижу кого, даю кому. Они требуют разных местоимений.',[
('Îl văd pe Andrei.','Я вижу Андрея.'),('O cunosc pe Ana.','Я знаю Ану.'),('Îi trimit un mesaj.','Я отправляю ему или ей сообщение.'),('Am văzut-o ieri.','Я видел её вчера.'),('Nu îl înțeleg.','Я его не понимаю.')],('Я вижу её: ___ văd.','O','Безударное прямое дополнение женского рода: o.')),
('b1-imperfect','B1','Фон и привычка в прошлом','Imperfect și perfect compus','Imperfect описывает длительный фон, состояние или повторение в прошлом: citeam. Perfect compus выделяет событие: a sunat. В рассказе эти времена дополняют друг друга. Выбор определяется ролью действия в контексте, а не только длительностью в минутах.','Слова mereu и în fiecare zi часто сопровождают привычку, но механическое правило по одному наречию ненадёжно.',[
('Când eram copil, locuiam la Brașov.','Когда я был ребёнком, я жил в Брашове.'),('Citeam când a sunat telefonul.','Я читал, когда зазвонил телефон.'),('În fiecare vară mergeam la bunici.','Каждое лето мы ездили к бабушке и дедушке.'),('Ieri am terminat raportul.','Вчера я закончил отчёт.'),('Afară ploua, iar noi așteptam trenul.','На улице шёл дождь, а мы ждали поезд.')],('Фоновое чтение: Eu ___ când ai venit. (a citi)','citeam','Imperfect: citeam — действие происходило в момент прихода.')),
('b1-subjunctive','B1','Желания и необходимость','Conjunctiv','Conjunctiv образуется с să и личной формой. Он часто следует после vreau, doresc, trebuie. Первое и второе лицо часто совпадают с настоящим временем, третье может отличаться: merge → să meargă. Глагол a fi имеет формы să fiu, să fii, să fie, să fim, să fiți, să fie.','Să — часть конструкции. После vreau не подставляйте английскую модель с голым инфинитивом.',[
('Vreau să învăț limba română.','Я хочу выучить румынский язык.'),('Trebuie să plecăm acum.','Нам нужно уходить сейчас.'),('Doresc să vorbesc cu directorul.','Я желаю поговорить с директором.'),('Este important să fii atent.','Важно быть внимательным.'),('Vreau ca el să vină mâine.','Я хочу, чтобы он пришёл завтра.')],('Пусть он идёт: să ___ (a merge)','meargă','Третье лицо conjunctiv: să meargă.')),
('b1-conditional','B1','Если бы у меня было время','Condițional prezent','Гипотетическое действие: aș, ai, ar, am, ați, ar + инфинитив без a. Конструкция используется в желаниях, советах и вежливых просьбах. В нереальном условии о настоящем condițional может быть в обеих частях: dacă aș avea timp, aș citi.','Не смешивайте будущее va с условным ar. Реальное условие и гипотеза передают разный смысл.',[
('Aș dori o cafea, vă rog.','Я хотел бы кофе, пожалуйста.'),('Dacă aș avea timp, aș călători mai mult.','Если бы у меня было время, я бы больше путешествовал.'),('Ai putea să repeți?','Ты мог бы повторить?'),('Noi am prefera altă soluție.','Мы предпочли бы другое решение.'),('Ar fi bine să verificăm datele.','Было бы хорошо проверить данные.')],('Я бы прочёл: Eu ___ citi.','aș','Первое лицо условного: aș citi.')),
('b1-relative','B1','Уточнить, о ком речь','Propoziții relative','Относительные предложения уточняют существительное. Для подлежащего используется care: omul care vine. Прямое дополнение обычно имеет pe care и дублирующее местоимение: cartea pe care am citit-o. Дательный требует căruia, căreia или cărora по числу и роду.','В выражении cartea pe care am citit-o нужны и pe, и местоимение o после причастия.',[
('Omul care vorbește este profesorul meu.','Человек, который говорит, — мой преподаватель.'),('Cartea pe care am citit-o este interesantă.','Книга, которую я прочёл, интересная.'),('Acesta este colegul căruia i-am scris.','Это коллега, которому я написал.'),('Orașul în care locuiesc este liniștit.','Город, в котором я живу, спокойный.'),('Caut persoana care a trimis mesajul.','Я ищу человека, который отправил сообщение.')],('Книга, которую я прочёл: cartea ___ am citit-o','pe care','Прямое относительное дополнение: pe care.')),
('b2-past-condition','B2','Несбывшееся прошлое','Condițional perfect','Нереальная ситуация в прошлом передаётся aș fi + причастие: aș fi venit. В условном придаточном возможна та же конструкция: Dacă aș fi știut, aș fi venit. Частица fi и причастие не меняются, меняется вспомогательная форма: ai fi, ar fi, am fi, ați fi.','Различайте aș veni — пришёл бы сейчас или потом, и aș fi venit — пришёл бы тогда, но этого не произошло.',[
('Dacă aș fi știut, aș fi venit.','Если бы я знал, я бы пришёл.'),('Ai fi putut să mă anunți.','Ты мог бы меня предупредить.'),('Am fi plecat mai devreme.','Мы бы уехали раньше.'),('Ea ar fi acceptat oferta.','Она бы приняла предложение.'),('Nu aș fi spus asta.','Я бы этого не сказал.')],('Он бы пришёл тогда: El ___ fi venit.','ar','Третье лицо condițional perfect: ar fi venit.')),
('b2-passive','B2','Процесс и исполнитель','Diateza pasivă','Пассив часто образуется a fi + причастие. В отличие от perfect compus, причастие согласуется с подлежащим: raportul este verificat, documentele sunt verificate. Исполнитель вводится de или de către. Выбирайте пассив, когда в центре внимания действие или его объект.','Am verificat — активное прошедшее; este verificat — пассив. Здесь причастие согласуется в роде и числе.',[
('Raportul este verificat de colegul meu.','Отчёт проверяется моим коллегой.'),('Documentele sunt verificate înainte de trimitere.','Документы проверяются перед отправкой.'),('Cererea a fost aprobată ieri.','Заявление было одобрено вчера.'),('Lucrările vor fi terminate vineri.','Работы будут закончены в пятницу.'),('Datele au fost corectate.','Данные были исправлены.')],('Документы проверены: Documentele sunt ___. (verificat)','verificate','Подлежащее documentele — мн. число; причастие verificate.')),
('b2-concession','B2','Уступка и противопоставление','Deși, chiar dacă, cu toate că','Уступка связывает ожидаемую причину и неожиданный результат: deși plouă, ieșim. Союзы deși и cu toate că вводят фактическую уступку. Chiar dacă может вводить допущение: даже если. Различайте факт и гипотезу, а не переводите все союзы одним шаблоном.','Deși обычно сочетается с изъявительным. Для гипотетических сравнений ca și cum нужна отдельная модель.',[
('Deși plouă, vom pleca.','Хотя идёт дождь, мы уедем.'),('Cu toate că era obosit, a continuat să lucreze.','Несмотря на усталость, он продолжил работать.'),('Chiar dacă nu ești de acord, te ascult.','Даже если ты не согласен, я тебя выслушаю.'),('Oferta este bună, însă are câteva limite.','Предложение хорошее, однако у него есть несколько ограничений.'),('Nu contest ideea, ci modul de aplicare.','Я оспариваю не идею, а способ её применения.')],('Хотя идёт дождь: ___ plouă, ieșim.','Deși','Deși вводит фактическую уступку.')),
('b2-reported','B2','Передать чужие слова','Vorbire indirectă','Чужое сообщение вводится că, косвенный вопрос — dacă или вопросительным словом. Время выбирается по реальному отношению событий; румынская речь не требует механического английского согласования всех времён. Указатели здесь/завтра и местоимения меняются с точкой зрения говорящего.','Dacă может означать «ли» в косвенном вопросе. Это не всегда условие «если».',[
('Ana a spus că va veni mâine.','Ана сказала, что придёт завтра.'),('M-a întrebat dacă am timp.','Он спросил меня, есть ли у меня время.'),('Nu știu unde locuiește.','Я не знаю, где он живёт.'),('Profesorul a explicat că regula are excepții.','Преподаватель объяснил, что у правила есть исключения.'),('Mi-a spus să aștept aici.','Он сказал мне подождать здесь.')],('Он спросил, приду ли я: A întrebat ___ voi veni.','dacă','Dacă вводит косвенный общий вопрос.')),
('c1-argument','C1','Сформулировать аргумент','Argumentare și nuanță','Стройте аргумент как тезис, основание, ограничение и вывод. Prin urmare указывает на следствие, în schimb — на противопоставление, în măsura în care ограничивает утверждение условием или степенью применимости. Не заменяйте проверку доказательств уверенной интонацией.','Уровень C1 требует не редких слов ради сложности, а точных связей между мыслями, уместного регистра и понимания оговорок.',[
('Datele sunt incomplete; prin urmare, concluzia rămâne provizorie.','Данные неполны; следовательно, вывод остаётся предварительным.'),('Nu contest utilitatea proiectului, ci prioritățile stabilite.','Я оспариваю не полезность проекта, а установленные приоритеты.'),('În măsura în care datele vor fi confirmate, vom menține concluzia.','Если данные будут подтверждены, мы сохраним вывод.'),('Pe de o parte, costurile scad; pe de altă parte, riscurile cresc.','С одной стороны, затраты снижаются; с другой — риски растут.'),('Această interpretare trebuie privită cu prudență.','К этой интерпретации следует относиться с осторожностью.')],('Следовательно: prin ___','urmare','Prin urmare связывает основание и вывод.')),
('c1-register','C1','Деловой и нейтральный регистр','Registru și politețe','Уместность зависит от адресата и цели. Неофициальное Poți să…? может стать Puteți să…? или V-aș ruga să… в обращении к незнакомому человеку. Деловая речь требует точного действия, срока и ответственности, а не только более длинных слов.','Не считайте длинную формулу автоматически более вежливой. Ясность просьбы и корректное обращение важнее канцелярского стиля.',[
('V-aș ruga să confirmați primirea documentelor.','Я попросил бы вас подтвердить получение документов.'),('Vă transmit, în anexă, raportul solicitat.','Направляю вам в приложении запрошенный отчёт.'),('Aș aprecia dacă ne-ați comunica decizia până vineri.','Я был бы признателен, если бы вы сообщили нам решение до пятницы.'),('În legătură cu solicitarea dumneavoastră, vă informăm că analiza continuă.','В связи с вашим запросом сообщаем, что рассмотрение продолжается.'),('Rămân la dispoziția dumneavoastră pentru clarificări.','Остаюсь в вашем распоряжении для уточнений.')],('Вежливо: V-___ ruga să confirmați.','aș','V-aș ruga — вежливая формула condițional.')),
('c1-relative','C1','Точная связь и согласование','Al cărui, a cărei, ai căror','В родительной относительной конструкции две связи согласования. Al/a/ai/ale согласуется с принадлежащим предметом, cărui/cărei/căror — с владельцем. В datele a căror exactitate… a относится к exactitate, а căror — к datele. Разбирайте обе связи отдельно.','Не выбирайте a только по ближайшему слову перед конструкцией: сначала определите, какой предмет кому принадлежит.',[
('Acesta este autorul a cărui carte am citit-o.','Это автор, книгу которого я прочёл.'),('Am discutat cu cercetătoarea ale cărei articole le cunosc.','Я поговорил с исследовательницей, статьи которой мне знакомы.'),('Datele a căror exactitate a fost verificată sunt publice.','Данные, точность которых была проверена, общедоступны.'),('Proiectul al cărui buget a crescut va fi revizuit.','Проект, бюджет которого вырос, будет пересмотрен.'),('Studenții ai căror profesori au participat au primit informațiile.','Студенты, чьи преподаватели участвовали, получили информацию.')],('Данные, точность которых: datele ___ exactitate a fost verificată','a căror','A согласуется с exactitate, căror — с datele.')),
('c1-inference','C1','Сообщить факт или предположение','Evidență și surse','Отделяйте установленное событие от сведений источника и собственной интерпретации. Potrivit raportului указывает на источник, se pare că — на неполную уверенность, nu rezultă că — на отсутствие логического вывода. Эти средства меняют ответственность за высказывание.','Уверенная грамматическая форма не доказывает истинность. Уточняйте источник и степень подтверждения, особенно в профессиональной речи.',[
('Potrivit raportului, verificarea a fost finalizată.','Согласно отчёту, проверка завершена.'),('Se pare că rezultatele inițiale nu au fost confirmate.','По-видимому, первоначальные результаты не подтвердились.'),('Din aceste date nu rezultă că măsura este eficientă.','Из этих данных не следует, что мера эффективна.'),('Concluzia depinde de validitatea ipotezelor.','Вывод зависит от обоснованности гипотез.'),('Afirmația trebuie susținută prin dovezi verificabile.','Утверждение должно быть подкреплено проверяемыми доказательствами.')],('Согласно отчёту: ___ raportului','Potrivit','Potrivit в значении «согласно» употребляется с дательным.')),
]
lessons=[]
for id,level,title,subtitle,rule,tip,pairs,form in rows:
 lessons.append(dict(id=id,level=level,title=title,subtitle=subtitle,rule=rule,tip=tip,minutes=14,pairs=[dict(ro=ro,ru=ru)for ro,ru in pairs],form=dict(zip(['prompt','answer','why'],form))))
Path('src/data/academy/course.json').write_text(json.dumps(lessons,ensure_ascii=False,indent=2)+'\n')
